        <Row title={row.title} score={row.score} reload={() => refresh(rows)} />
      ))}
    </ul>
  );
}
function Clock() {
  const [tick, setTick] = createSignal(0);
  // F-S42: the effect's returned cleanup runs before the next run.
  createEffect(
    () => tick(),
    value => {
